UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"hdr","type":"header","label":"Шапка","content":"Приложение № 4 к договору бытового подряда на изготовление мебели № {{номер_договора}} от {{дата_договора}}","enabled":true},
  {"id":"title","type":"section","label":"Заголовок","content":"«АКТ ВЫПОЛНЕННЫХ РАБОТ»","enabled":true},
  {"id":"date","type":"paragraph","label":"Дата","content":"от «____» ________________ 20____ г.","enabled":true},
  {"id":"intro","type":"paragraph","label":"Преамбула","content":"{{компания}}, в лице менеджера {{менеджер}}, действующего на основании доверенности № {{номер_доверенности}} от {{дата_доверенности}}, именуемый в дальнейшем «Подрядчик», и гр. {{имя_клиента}}, именуемый (ая) в дальнейшем «Заказчик», подписали настоящий Акт выполненных работ о нижеследующем:","enabled":true},
  {"id":"p1","type":"paragraph","label":"1 — Изготовлено","content":"1. Подрядчик изготовил для Заказчика мебель по договору бытового подряда № {{номер_договора}} от {{дата_договора}}:","enabled":true},
  {"id":"p2","type":"paragraph","label":"2 — Комплектность","content":"2. Комплектность, количество, вид, характеристики мебели соответствуют условиям договора. Визуальный осмотр мебели на предмет повреждений, царапин, сколов, трещин и других недостатков произведён Заказчиком. Фурнитура (петли, выдвижные механизмы, подъёмные механизмы и т.д.) работает исправно. Заказчик претензий по объёму, качеству, результату и срокам выполнения работ: не имеет / имеет (ненужное зачеркнуть).","enabled":true},
  {"id":"p3","type":"paragraph","label":"3 — Замечания","content":"3. В случае наличия замечаний Заказчик, после подписания акта, вправе требовать устранения замечаний, отражённых в данном акте.","enabled":true},
  {"id":"p4","type":"paragraph","label":"4 — Экземпляры","content":"4. Настоящий акт подписан в 2 (двух) экземплярах по одному для каждой из Сторон.","enabled":true},
  {"id":"sign","type":"paragraph","label":"Подписи","content":"Подрядчик: {{компания}}\nМенеджер: {{менеджер}}\n\n_________________________\n(подпись) М.П.\n\nЗаказчик: {{имя_клиента}}\n\n_________________________\n(подпись)","enabled":true}
]'::jsonb, updated_at = now() WHERE id = 'a775c807-a834-4406-9a8d-fbb884ee2ddc';

