  {"id":"title","type":"section","label":"Заголовок","content":"«АКТ ПРИЁМА-ПЕРЕДАЧИ ВЫПОЛНЕННЫХ РАБОТ ПО СБОРКЕ И МОНТАЖУ МЕБЕЛИ»","enabled":true},
