UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"title","type":"section","label":"Заголовок","content":"ДОГОВОР","enabled":true},
  {"id":"sub","type":"header","label":"Подзаголовок","content":"на оказание услуг по сборке и монтажу мебели","enabled":true},
  {"id":"date","type":"paragraph","label":"Город и дата","content":"г. {{город}}, {{дата_договора}}","enabled":true},
  {"id":"intro","type":"paragraph","label":"Преамбула","content":"{{компания}}, в лице менеджера {{менеджер}}, именуемый «Исполнитель», и гр. {{имя_клиента}}, именуемый «Заказчик», заключили настоящий Договор:","enabled":true},
  {"id":"s1","type":"section","label":"1. ПРЕДМЕТ ДОГОВОРА","content":"1. ПРЕДМЕТ ДОГОВОРА","enabled":true},
  {"id":"s1p1","type":"paragraph","label":"1.1","content":"1.1. Исполнитель обязуется выполнить работы по сборке и монтажу мебели по договору подряда № {{номер_договора}} от {{дата_договора}}.","enabled":true},
  {"id":"s1p2","type":"paragraph","label":"1.2","content":"1.2. Адрес выполнения работ: {{адрес_доставки}}.","enabled":true},
  {"id":"s1p3","type":"paragraph","label":"1.3","content":"1.3. Ориентировочная дата начала работ: {{дата_доставки}}. Срок выполнения: {{дни_сборки}} рабочих дней.","enabled":true},
  {"id":"s1p4","type":"paragraph","label":"1.4","content":"1.4. В объём работ входит: сборка корпусных элементов, установка фасадов и фурнитуры, регулировка петель, монтаж столешницы и стеновых панелей, подключение подсветки (при наличии).","enabled":true},
  {"id":"s2","type":"section","label":"2. ПРАВА И ОБЯЗАННОСТИ СТОРОН","content":"2. ПРАВА И ОБЯЗАННОСТИ СТОРОН","enabled":true},
  {"id":"s2p1","type":"paragraph","label":"2.1","content":"2.1. Исполнитель обязан: выполнить монтаж качественно; убрать строительный мусор; уведомить о дефектах мебели или помещения.","enabled":true},
  {"id":"s2p2","type":"paragraph","label":"2.2","content":"2.2. Заказчик обязан: обеспечить доступ и электроснабжение; принять работы; оплатить согласно условиям.","enabled":true},
  {"id":"s3","type":"section","label":"3. СТОИМОСТЬ И ОПЛАТА","content":"3. СТОИМОСТЬ И ОПЛАТА","enabled":true},
  {"id":"s3p1","type":"paragraph","label":"3.1","content":"3.1. Стоимость работ по сборке и монтажу составляет {{стоимость_сборки}} рублей.","enabled":true},
  {"id":"s3p2","type":"paragraph","label":"3.2","content":"3.2. Оплата производится в день завершения монтажных работ до подписания Акта приёмки.","enabled":true},
  {"id":"s4","type":"section","label":"4. ОТВЕТСТВЕННОСТЬ","content":"4. ОТВЕТСТВЕННОСТЬ","enabled":true},
  {"id":"s4p1","type":"paragraph","label":"4.1","content":"4.1. Исполнитель несёт ответственность за качество монтажных работ в течение 12 месяцев.","enabled":true},
  {"id":"s4p2","type":"paragraph","label":"4.2","content":"4.2. Гарантия не распространяется на дефекты от нарушения правил эксплуатации или механических повреждений.","enabled":true},
  {"id":"s5","type":"section","label":"5. ПРОЧИЕ УСЛОВИЯ","content":"5. ПРОЧИЕ УСЛОВИЯ","enabled":true},
  {"id":"s5p1","type":"paragraph","label":"5.1","content":"5.1. Приёмка работ оформляется подписанием Акта приёмки. Договор составлен в двух экземплярах.","enabled":true},
  {"id":"sign","type":"paragraph","label":"Подписи","content":"Исполнитель: {{компания}}\nМенеджер: {{менеджер}}\n\n_________________________\n(подпись) М.П.\n\nЗаказчик: {{имя_клиента}}\nАдрес монтажа: {{адрес_доставки}}\nТелефон: {{телефон}}\n\n_________________________\n(подпись)","enabled":true}
]'::jsonb, updated_at = now() WHERE id = '39359828-1a3f-4763-a584-6a0a3510d22b';

-- delivery
UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"title","type":"section","label":"Заголовок","content":"ДОГОВОР","enabled":true},
  {"id":"sub","type":"header","label":"Подзаголовок","content":"на оказание услуг по доставке мебели","enabled":true},
  {"id":"date","type":"paragraph","label":"Город и дата","content":"г. {{город}}, {{дата_договора}}","enabled":true},
  {"id":"intro","type":"paragraph","label":"Преамбула","content":"{{компания}}, в лице менеджера {{менеджер}}, именуемый «Исполнитель», и гр. {{имя_клиента}}, именуемый «Заказчик», заключили настоящий Договор:","enabled":true},
  {"id":"s1","type":"section","label":"1. ПРЕДМЕТ ДОГОВОРА","content":"1. ПРЕДМЕТ ДОГОВОРА","enabled":true},
  {"id":"s1p1","type":"paragraph","label":"1.1","content":"1.1. Исполнитель обязуется доставить мебель по договору подряда № {{номер_договора}} от {{дата_договора}}.","enabled":true},
  {"id":"s1p2","type":"paragraph","label":"1.2","content":"1.2. Адрес доставки: {{адрес_доставки}}. Этаж: {{этаж_доставки}}. Лифт: {{лифт_доставки}}.","enabled":true},
  {"id":"s1p3","type":"paragraph","label":"1.3","content":"1.3. Дата доставки: {{дата_доставки}}. Конкретное время согласовывается дополнительно.","enabled":true},
  {"id":"s1p4","type":"paragraph","label":"1.4","content":"1.4. Доставка осуществляется в разобранном виде.","enabled":true},
  {"id":"s2","type":"section","label":"2. ПРАВА И ОБЯЗАННОСТИ СТОРОН","content":"2. ПРАВА И ОБЯЗАННОСТИ СТОРОН","enabled":true},
  {"id":"s2p1","type":"paragraph","label":"2.1","content":"2.1. Исполнитель обязан: доставить в срок по указанному адресу; обеспечить сохранность при транспортировке; уведомить об изменении времени не менее чем за 2 часа.","enabled":true},
  {"id":"s2p2","type":"paragraph","label":"2.2","content":"2.2. Заказчик обязан: обеспечить доступ к месту доставки; оплатить услуги; при обнаружении повреждений сообщить до подписания акта.","enabled":true},
  {"id":"s2p3","type":"paragraph","label":"2.3","content":"2.3. Исполнитель вправе однократно предоставить скидку в размере стоимости доставки (8 000 руб.) при доставке в пределах г. Саратова и г. Энгельса.","enabled":true},
  {"id":"s3","type":"section","label":"3. СТОИМОСТЬ И ОПЛАТА","content":"3. СТОИМОСТЬ И ОПЛАТА","enabled":true},
  {"id":"s3p1","type":"paragraph","label":"3.1","content":"3.1. Стоимость услуг определяется Приложением № 1.","enabled":true},
  {"id":"s3p2","type":"paragraph","label":"3.2","content":"3.2. Оплата производится в день доставки до начала разгрузки.","enabled":true},
  {"id":"s4","type":"section","label":"4. ОТВЕТСТВЕННОСТЬ","content":"4. ОТВЕТСТВЕННОСТЬ","enabled":true},
  {"id":"s4p1","type":"paragraph","label":"4.1","content":"4.1. При повреждении мебели по вине Исполнителя при транспортировке — Исполнитель возмещает ущерб.","enabled":true},
  {"id":"s4p2","type":"paragraph","label":"4.2","content":"4.2. При отказе от доставки менее чем за 24 часа Исполнитель вправе удержать фактически понесённые расходы.","enabled":true},
  {"id":"s5","type":"section","label":"5. ПРОЧИЕ УСЛОВИЯ","content":"5. ПРОЧИЕ УСЛОВИЯ","enabled":true},
  {"id":"s5p1","type":"paragraph","label":"5.1","content":"5.1. Договор вступает в силу с момента подписания. Составлен в двух экземплярах.","enabled":true},
  {"id":"sign","type":"paragraph","label":"Подписи","content":"Исполнитель: {{компания}}\nМенеджер: {{менеджер}}\n\n_________________________\n(подпись) М.П.\n\nЗаказчик: {{имя_клиента}}\nТелефон: {{телефон}}\n\n_________________________\n(подпись)","enabled":true}
]'::jsonb, updated_at = now() WHERE id = '47793a60-ce5e-4958-9063-360fde6de7ef';

-- rules
UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"hdr","type":"header","label":"Шапка","content":"Приложение № 3 к договору бытового подряда на изготовление мебели № {{номер_договора}} от {{дата_договора}}","enabled":true},
  {"id":"title","type":"section","label":"Заголовок","content":"ПРАВИЛА ЭКСПЛУАТАЦИИ КОРПУСНОЙ МЕБЕЛИ","enabled":true},
  {"id":"s1","type":"section","label":"1. ОБЩИЕ РЕКОМЕНДАЦИИ","content":"1. ОБЩИЕ РЕКОМЕНДАЦИИ","enabled":true},
  {"id":"s1p1","type":"paragraph","label":"1.1","content":"1.1. Срок службы мебели и сохранение её потребительских свойств напрямую зависят от соблюдения Заказчиком правил, изложенных в настоящем приложении.","enabled":true},
  {"id":"s1p2","type":"paragraph","label":"1.2","content":"1.2. Мебель предназначена для использования в закрытых жилых и офисных помещениях при нормальных условиях окружающей среды.","enabled":true},
  {"id":"s1p3","type":"paragraph","label":"1.3 — Климат","content":"1.3. Оптимальные условия эксплуатации: температура воздуха от +18°C до +25°C, относительная влажность воздуха 45% — 70%.","enabled":true},
  {"id":"s2","type":"section","label":"2. УСЛОВИЯ ХРАНЕНИЯ","content":"2. УСЛОВИЯ ХРАНЕНИЯ","enabled":true},
  {"id":"s2p1","type":"paragraph","label":"2.1","content":"2.1. Хранение мебели до её установки должно осуществляться в сухих, проветриваемых, отапливаемых помещениях.","enabled":true},
  {"id":"s2p2","type":"paragraph","label":"2.2","content":"2.2. Не допускается хранение мебели под открытым небом, в условиях повышенной влажности или вблизи источников тепла.","enabled":true},
  {"id":"s3","type":"section","label":"3. ПРАВИЛА ЭКСПЛУАТАЦИИ","content":"3. ПРАВИЛА ЭКСПЛУАТАЦИИ И УХОДА ЗА МЕБЕЛЬЮ","enabled":true},
  {"id":"s3p1","type":"paragraph","label":"3.1 — Общие","content":"3.1. Для чистки поверхностей мебели используйте мягкую ткань, слегка смоченную водой или специальным средством для ухода за мебелью. Не используйте абразивные материалы и агрессивные химические вещества.","enabled":true},
  {"id":"s3ldsp","type":"paragraph","label":"3.2 — ЛДСП","content":"3.2. Корпус ЛДСП: немедленно вытирать пролитое. Не мыть водой, не использовать пароочистители и абразивы. Не допускать длительного воздействия влаги на торцы и кромки.","enabled":true},
  {"id":"s3mdf","type":"paragraph","label":"3.3 — МДФ","content":"3.3. Фасады МДФ: не допускать контакта с горячим (свыше +60°C), острыми предметами, агрессивной химией. Царапины полировать специальными составами.","enabled":true},
  {"id":"s3table","type":"paragraph","label":"3.4 — Столешницы","content":"3.4. Столешницы: не использовать как разделочную доску. Сразу убирать воду, особенно на стыках и у мойки. Не ставить горячее без подставки.","enabled":true},
  {"id":"s3glass","type":"paragraph","label":"3.5 — Стеклянные фасады","content":"3.5. Стеклянные фасады: протирать стеклоочистителем без абразивов. Не подвергать ударным нагрузкам.","enabled":true},
  {"id":"warn","type":"paragraph","label":"Предупреждение","content":"ВНИМАНИЕ! Подрядчик не несёт ответственность за последствия от несоблюдения установленных норм и правил по уходу и эксплуатации корпусной мебели.","enabled":true}
]'::jsonb, updated_at = now() WHERE id = 'e8702c4c-2889-4108-8b9c-317a79ee195e';

